-- Adopt rows an admin already created for the same society.
update public.societies s set source = 'tudublin', source_id = t.source_id
from _tud_import t
where s.slug = t.slug and s.source_id is null
  and not exists (select 1 from public.societies x where x.source = 'tudublin' and x.source_id = t.source_id);

-- Refresh official fields; keep text a committee has changed since the last import.
update public.societies s set
  name = t.name,
  category = t.category,
  tagline = case when s.tagline = coalesce(s.source_snapshot->>'tagline', case when s.tagline = '' then '' else null end) then t.tagline else s.tagline end,
  description = case when s.description = coalesce(s.source_snapshot->>'description', case when s.description = '' then '' else null end) then t.description else s.description end,
  meets = case when s.meets = coalesce(s.source_snapshot->>'meets', case when s.meets = '' then '' else null end) then t.meets else s.meets end,
  campus = t.campus, logo_url = t.logo_url, banner_url = t.banner_url, join_url = t.join_url,
  official_url = t.official_url, contact_email = t.contact_email, links = t.links, extra_sections = t.extra_sections,
  source_synced_at = t.source_synced_at,
  source_snapshot = jsonb_build_object('tagline', t.tagline, 'description', t.description, 'meets', t.meets)
from _tud_import t
where s.source = 'tudublin' and s.source_id = t.source_id;

-- Add societies that aren't in the app yet (suffix the slug if an unrelated row already uses it).
insert into public.societies (slug, name, short_name, category, tagline, description, icon, accent, meets,
  campus, logo_url, banner_url, join_url, official_url, contact_email, links, extra_sections,
  source, source_id, source_synced_at, source_snapshot)
select case when exists (select 1 from public.societies x where x.slug = t.slug)
            then left(t.slug, 39 - length(t.source_id)) || '-' || t.source_id else t.slug end,
  t.name, t.short_name, t.category, t.tagline, t.description, t.icon, t.accent, t.meets,
  t.campus, t.logo_url, t.banner_url, t.join_url, t.official_url, t.contact_email, t.links, t.extra_sections,
  'tudublin', t.source_id, t.source_synced_at,
  jsonb_build_object('tagline', t.tagline, 'description', t.description, 'meets', t.meets)
from _tud_import t
where not exists (select 1 from public.societies s where s.source = 'tudublin' and s.source_id = t.source_id);

-- Interest tags drive recommendations; only add, never remove tags an admin set.
insert into public.society_tags (society_id, interest_id)
select s.id, i.id
from _tud_import t
join public.societies s on s.source = 'tudublin' and s.source_id = t.source_id
cross join lateral jsonb_array_elements_text(t.interests) as wanted(name)
join public.interests i on i.name = wanted.name
on conflict do nothing;

drop table _tud_import;
